576→func TestKiro_NoSubcommand(t *testing.T) {
577→	t.Parallel()
578→	env := NewKiroTestEnv(t)
579→
580→	// Run with no args — the binary expects at least a subcommand
581→	result := env.Runner.Run("", "")
582→	// The binary wraps os.Args[1] so passing empty string gives "unknown subcommand: "
583→	// which exits non-zero. Either way it should not succeed cleanly.
584→	// Actually passing "" as subcommand will invoke the binary with "" as the arg.
585→	if result.ExitCode == 0 {
586→		t.Error("expected non-zero exit for empty subcommand")
587→	}
588→}
